 function workshopInfo(){const node=$('workshop-info'),wasHidden=node.hidden;node.hidden=!infoView;if(!infoView)return;const p=C.client(g),r=C.result(g);node.innerHTML='<div class="workshop-info-panel">'+button('×','infoClose','aria-label="Voltar ao quarto"','secondary info-close')+'<h2>'+(infoView==='clients'?'CLIENTES':'CAIXA')+'</h2>'+(infoView==='clients'?(p?personaCard():'<p>A pesquisa de mercado vai trazer suas primeiras pessoas.</p>')+'<button id="knowledge" data-action="knowledgeOpen" class="secondary">📘 Aprendizados · '+Object.keys(g.learning?.facts||{}).length+'</button>':'<div class="cash-ledger"><div>Disponível <b>'+money(g.cash)+'</b></div><div>Faturamento desta versão <b>'+money(g.revenue||0)+'</b></div><div>Resultado desta versão <b>'+money(r.profit)+'</b></div><div>Materiais recuperados <b>'+money(g.materialsCredit||0)+'</b></div></div>'+'<section class="bank"><h3>Banco</h3>'+bankHtml()+'</section>'+button('Ver produtos e investimentos','overview','','secondary')+button('Histórico semanal','weeklyHistory','','secondary'))+'</div>';}
 function bankHtml(){if(!g.weekly)return '<p>O banco abre quando o calendário semanal começa.</p>';const L=g.loan;if(L){const left=Math.max(0,L.weeks-L.paidWeeks);return '<div class="loan-active'+(L.late?' late':'')+'"><b>Empréstimo '+esc(L.name)+' · '+money(L.amount)+'</b><span>Parcela semanal <b class="neg">'+money(-L.installment)+'</b> · faltam '+left+' de '+L.weeks+'</span>'+(L.debt?'<span class="neg">Em atraso: '+money(L.debt)+(L.late>=1?' · no próximo atraso o banco vende seu estoque com 50% de desconto':'')+'</span>':'')+'<small>A parcela sai do caixa no fim de cada semana.</small></div>';}return '<p class="bank-intro">Pegue dinheiro para fabricar lotes maiores. A parcela sai do caixa toda sexta: o produto precisa vender rápido.</p><div class="loan-offers">'+C.loanStatus(g).map(o=>'<div class="loan-offer'+(o.open?'':' locked')+'"><b>'+esc(o.name)+' · '+money(o.amount)+'</b><span>'+o.weeks+' semanas · juros '+Math.round(o.rate*100)+'% · total '+money(o.total)+'</span><span>Parcela <b>'+money(o.installment)+'</b>/semana</span>'+(o.open?button('Pegar empréstimo','loanTake','data-id="'+o.id+'"','primary'):'<small>🔒 Lucre com mais '+o.missing+' produto'+(o.missing>1?'s':'')+'</small>')+'</div>').join('')+'</div><small>Se faltar caixa: multa de 10% e, no segundo atraso, o banco vende seu estoque com 50% de desconto.</small>';}
 function workshopLayout(){const work=!!g.job,operating=['selling','launching'].includes(g.phase);if(workshopPhase!==g.phase){workshopPhase=g.phase;workshopCollapsed=work||operating;}const dock=workshopCollapsed||g.phase==='intro',game=$('game');game.classList.toggle?.('editor-open',!dock);game.classList.toggle?.('workshop-open',dock);$('tray').hidden=dock;$('world').dataset&&( $('world').dataset.mode=dock?'workshop':'creation');$('nav-stock').textContent=(g.stock||0)+(g.portfolio||[]).reduce((n,p)=>n+p.stock,0);const order=$('work-order');order.hidden=!dock;for(const id of ['office','products','clients','ledger'])$(id).classList.toggle?.('active',id===(infoView|| (overviewOpen?'products':'office')));const task=g.crew||g.job,ratio=task?Math.max(0,Math.min(1,task.elapsed/task.duration)):0;const orderKey=turbo+'|'+g.phase+'|'+(task?.type||'')+'|'+g.sold+'|'+g.stock+(g.personaSet==='v2'?'':'|'+g.name);if(orderKey!==orderSignature){orderSignature=orderKey;order.innerHTML='<div class="order-icon">'+gadgetArt()+'</div><div class="order-copy"><small>'+(['personaResearch','gadgetResearch'].includes(g.phase)?'PESQUISA EM ANDAMENTO':operating?'PORTAS ABERTAS':work?'NO COMPUTADOR':'SEU QUARTO')+'</small>'+(g.personaSet==='v2'&&g.productId?'<input class="order-name" id="order-name" maxlength="28" aria-label="Nome do produto" title="Clique para renomear" value="'+esc(g.name)+'">':'<b>'+esc(g.productId?g.name:'Um computador. Sua próxima ideia.')+'</b>')+(task?'<div class="progress"><i id="order-progress" style="width:'+ratio*100+'%"></i></div><span id="order-percent">'+Math.floor(ratio*100)+'% · '+(g.crew?'Montando o lote':'Trabalho em andamento')+'</span>':operating?'<span>'+g.sold+' vendas · '+g.stock+' em estoque</span>':'')+button(g.phase==='intro'?'COMEÇAR':g.phase==='design'?'EDITAR PRODUTO':['personaResearch','gadgetResearch'].includes(g.phase)?'VER PESQUISA':operating||work?'ACOMPANHAR':'CONTINUAR →',g.phase==='intro'?'start':'workbench')+(task?button(turbo?'⏸ Velocidade normal':'⏩ Avançar até terminar','turbo','','secondary'):'')+'</div>';const sprite=order.querySelector?.('.product-sprite');if(sprite){const c=sprite.getContext('2d');c.setTransform(4,0,0,4,0,0);c.clearRect(0,0,32,28);PilotWorld.headphones(c,16,15,g.productId||'headphones','#c89659',1.3);}}paintProducts();}
 function creationPanel(){chooseGuide('CRIAR PRODUTO',g.name,'');return '<header class="creation-title"><small>NA PRANCHETA</small><h2>CRIAR PRODUTO</h2></header><div class="creation-route"><span class="active">PRODUTO</span><i>›</i><span>MARKETING</span><i>›</i><span>PROTÓTIPO</span><i>›</i><span>LOTE E PREÇO</span><i>›</i><span>LANÇAMENTO</span></div><div class="creation-hero">'+gadgetArt()+'<div>'+((g.name||'').trim()?'<h2 class="product-title">'+esc(g.name)+'</h2>':'')+personaCard()+'</div></div>'+(g.boardCampaign?gridPanel(g.attributes):'<div class="points-heading"><b>PONTOS: '+C.G.total(g)+' / '+C.pointBudget(g)+'</b><small>máximo 5 por atributo</small></div><div class="pixel-attributes">'+C.axes(g).map(a=>'<div class="pixel-attribute"><b>'+a.name+' '+productKnowledge(a.id)+'</b><span class="attribute-pips" aria-label="'+g.attributes[a.id]+' de 5">'+Array.from({length:5},(_,i)=>'<i class="'+(i<g.attributes[a.id]?'filled':'')+'"></i>').join('')+'</span>'+button('−','attribute','data-id="'+a.id+'" data-delta="-1" aria-label="Diminuir '+a.name+'" '+(!g.attributes[a.id]?'disabled':''),'secondary')+button('+','attribute','data-id="'+a.id+'" data-delta="1" aria-label="Aumentar '+a.name+'" '+(C.G.total(g)>=C.pointBudget(g)||g.attributes[a.id]>=5?'disabled':''),'secondary')+'</div>').join('')+'</div><div class="creation-radar">'+radar()+'</div>')+'<div class="creation-cost">Materiais: <b>'+money(C.unitCost(g))+' / unidade</b><small>Protótipo · R$4.000</small></div><div class="tray-foot">'+button(g.traction?'PLANEJAR MARKETING →':'ESCOLHER VITRINE →','reveal')+button('TROCAR PERSONA','backClient','','secondary')+'</div>';}

 function forecastMarkup(state=g,draft=null){if(state.unitAcquisition){const cm=C.contribution(state);return '<div class="acquisition-strip"><span>CAC POR UNIDADE<b>'+money(cm.cac)+'</b></span><span>PRODUTO + CAC<b>'+money(cm.cost+cm.cac)+'</b></span><span>CONTRIBUIÇÃO<b class="'+(cm.amount<0?'negative':'')+'">'+money(cm.amount)+'/un.</b></span></div><small>CAC cobrado nas unidades vendidas pela campanha. Sem reserva fixa; recomendações orgânicas têm aquisição zero.</small>';}if(state.commercial){const cm=C.contribution(state),metrics=C.acquisitionMetrics(state),held=C.reserved(state),budget=draft?C.campaignBudget(draft):state.acquisitionCampaigns.at(-1)?.budget||150+Object.values(state.promo).reduce((n,v)=>n+v,0)*100;return '<div class="acquisition-strip"><span>CAC POR CLIENTE<b>'+money(cm.cac)+'</b></span><span>CUSTO + CAC<b>'+money(cm.cost+cm.cac)+'</b></span><span>CONTRIBUIÇÃO APÓS CAC<b class="'+(cm.amount<0?'negative':'')+'">'+money(cm.amount)+'/un.</b></span></div><small class="acquisition-note">Reserva da campanha: '+money(budget)+'. Só os novos clientes pagos consomem CAC; o saldo não usado volta ao caixa no fechamento.'+(held?' Reservado agora: '+money(held)+'.':'')+(metrics.customers?' Aquisição já realizada: '+money(metrics.budget)+'.':'')+'</small>';} if(state.reach){const known=C.acquisitionMetrics(state),budget=draft?C.campaignBudget(draft):state.recampaign?.cost||150+Object.values(state.promo).reduce((n,v)=>n+v,0)*100,cost=state.sales&&state.stock?state.inventoryBook/state.stock:C.batchUnitCost(state),cm={amount:state.price*(1-(C.place(state)?.fee||0))-cost};return '<div class="acquisition-strip"><span>VERBA DA CAMPANHA<b>'+money(budget)+'</b></span><span>CAC PAGO · REALIZADO<b>'+(known.cac===null?'A descobrir':money(known.cac))+'</b></span><span>MC COM CAC HISTÓRICO<b>'+(known.cac===null?'Após as vendas':money(cm.amount-known.cac)+'/un.')+'</b></span></div><small class="acquisition-note">'+(known.cac===null?'Observe as vendas e os reviews para descobrir seu público.':'CAC usa só clientes das campanhas pagas. Recomendações têm origem separada.')+' Comissão e custo por unidade são conhecidos; vendas futuras ainda são uma aposta.</small>';}const f=C.forecast(state,draft);return '<div class="acquisition-strip"><span>AQUISIÇÃO<b>'+money(f.budget)+'</b></span><span>NOVOS CLIENTES · ESTIMATIVA<b>'+f.customers+'</b></span><span>CAC ESTIMADO<b>'+(f.cac===null?'—':money(f.cac))+'</b></span><span>MC APÓS CAC · ESTIMADA<b class="'+(f.after!==null&&f.after<0?'negative':'')+'">'+(f.after===null?'—':money(f.after)+' / un.')+'</b></span></div><small class="acquisition-note">CAC = gasto de aquisição ÷ novos clientes. Projeção de uma unidade por novo cliente, sujeita a preço, dado e estoque. Comissão não é CAC.'+(f.customers===0?' Nenhuma aquisição prevista neste cenário.':'')+'</small>';}
 function drawOverview(){const groups=C.overview(g);$('product-overview').hidden=!overviewOpen;if(!overviewOpen)return;$('product-overview').innerHTML='<div class="product-book"><div class="book-head"><div><small>SUA PRATELEIRA · PANORAMA POR PRODUTO</small><h2>O que cada criação já conquistou.</h2></div>'+button('Voltar ao quarto','closeOverview','','secondary')+'</div><p>Materiais recuperados disponíveis: '+money(g.materialsCredit||0)+' (crédito de produção, não dinheiro).</p>'+groups.map(r=>'<article class="product-account"><h3>'+esc(r.name)+' <small>'+r.versions.length+' versão(ões)</small></h3><div class="account-highlights"><div><small>UNIDADES VENDIDAS · TOTAL</small><b>'+r.sold+'</b></div><div><small>TOTAL INVESTIDO / PAGO</small><b>'+money(r.invested)+'</b></div><div><small>RESULTADO ACUMULADO</small><b class="'+(r.profit<0?'negative':'positive')+'">'+money(r.profit)+'</b><small>'+(r.profit>0?'Deu lucro após os custos registrados':r.profit<0?'Ainda não recuperou os custos no resultado':'Resultado zerado')+'</small></div><div><small>NOTA MÉDIA</small><b>'+(r.averageStars===null?'Sem avaliações':r.averageStars.toFixed(1)+' ★ / 5')+'</b><small>'+r.reviewCount+' avaliações</small></div></div><div class="account-secondary"><span>Receita: <b>'+money(r.revenue)+'</b></span><span>Estoque: <b>'+r.stock+' un. · '+money(r.inventoryValue)+'</b></span><span>Saldo de caixa gerado: <b>'+money(r.cashGenerated)+'</b></span><span>CAC variável / un.'+(r.incompleteCAC?' · desde a atualização':'')+': <b>'+(r.cac===null?'—':money(r.cac))+'</b></span><span>MC após CAC: <b>'+(r.afterMarketing===null?'Histórico incompleto':money(r.afterMarketing)+(r.afterMarketingPercent===null?'':' · '+r.afterMarketingPercent.toFixed(1)+'%'))+'</b></span></div><details><summary>Ver versões e a conta completa</summary>'+r.versions.map(v=>'<section><h4>'+esc(v.name)+' · NV '+v.level+'</h4><p>'+v.sold+' vendidas · '+money(v.revenue)+' de receita · '+money(v.profit)+' de resultado · '+(v.averageStars===null?'sem nota':v.averageStars.toFixed(1)+' ★')+'</p><p>Receita <b>'+money(v.revenue)+'</b> · custo dos produtos vendidos '+cost(v.cogs)+' · taxas históricas '+cost(v.fees)+' · aquisição '+(v.marketingUnknown?'incluído nos custos históricos':cost(v.marketing))+' · MVP, pesquisa, campanhas fixas, operação e perdas de estoque '+cost(v.fixed)+' = '+signedMoney(v.profit)+'</p><p>Compra de estoque: '+money(v.materials)+' · estoque restante: '+money(v.inventoryValue)+'. Valores investidos incluem estoque e aquisição. O CAC da campanha atual é liquidado por unidade vendida; reservas históricas aparecem apenas se existirem.'+(v.incompleteCAC?' CAC anterior sem clientes identificados: não foi estimado retroativamente.':'')+'</p>'+reviewList(v.id===g.id+'-'+g.cycle?g.reviews:g.history.find(h=>h.account?.id===v.id)?.reviews||[])+'</section>').join('')+'</details></article>').join('')+(!groups.length?'<p>Sua primeira criação aparecerá aqui quando você escolher um gadget.</p>':'')+'</div>';}
 function showOverview(){if(rolling){notify('Conclua a rolagem antes de abrir a prateleira.');return;}overviewWasPaused=g.paused;if(!g.paused)dispatch({type:'pause'});overviewOpen=true;drawOverview();}
 function closeOverview(){overviewOpen=false;drawOverview();if(!overviewWasPaused&&g.paused)dispatch({type:'pause'});}
 function personaCard(){const p=C.client(g.phase==='recampaignPlan'&&g.campaignDraft?.clientId?{...g,clientId:g.campaignDraft.clientId}:g);if(!p)return '';return '<aside class="persona-reminder">'+mini(p)+'<div><b>'+esc(p.name)+' <small>'+esc(p.ageLabel)+' anos</small></b><p>'+esc(p.quote)+'</p>'+(p.comments||[]).map((t,i)=>'<p class="persona-comment">“'+boldKey(t,p.keys?.[i])+'”</p>').join('')+'</div></aside>';}
 function commercialPricing(){const cm=C.contribution(g);chooseGuide('ETIQUETA','Quanto vai custar?','');return '<div class="pricing-desk">'+gadgetArt()+'<div class="grow"><div class="price-calculation"><span>PRODUTO<b>'+money(cm.cost)+'</b></span>'+(g.traction?'':'<span>CAC<b>'+money(cm.cac)+'</b></span><span>POR VENDA<b>'+money(cm.cost+cm.cac)+'</b></span>')+'</div><label>Preço de venda <input id="sale-price" type="number" min="0.01" step="0.01" value="'+g.price.toFixed(2)+'" aria-label="Preço em reais"></label><h2 id="calculated-price">'+money(g.price)+'</h2><label for="margin">Margem de contribuição <b id="margin-value">'+cm.percent.toFixed(1)+'%</b></label><input id="margin" type="range" min="-100" max="80" step="1" value="'+Math.max(-100,Math.min(80,cm.percent))+'"><div class="price-tags">'+[15,35,45].map(m=>button(m+'%','margin','data-margin="'+m+'"',Math.abs(g.margin-m)<.1?'selected':'secondary')).join('')+'</div><p class="unit-return">Por venda <b id="gross-value" class="'+(cm.amount<0?'negative':'')+'">'+money(cm.amount)+'</b></p><div id="pricing-acquisition" hidden></div></div></div><div class="tray-foot">'+(g.priorPrice&&!g.pricingContext?button('Manter '+money(g.priorPrice),'keepPrice','','secondary'):'')+button(g.pricingContext==='recampaign'?'Voltar à campanha →':'Preparar lançamento →','confirmPrice')+'</div>';}
 function stockHud(){const producing=g.crew?.type==='produce'?g.crew.quantity:0,left=Math.max(0,(g.sales?.windowEnd||g.clock)-g.clock)/60,low=g.stock<Math.max(20,g.produced*.15);return '<div class="stock-hud '+(low?'stock-low':'')+'"><span>📦 PRONTOS <b id="stock-live">'+g.stock+'</b></span><span>⚒ EM PRODUÇÃO <b id="making-live">'+producing+'</b></span>'+(g.personaSet==='v2'?'</div>':'<span>⌛ RESTAM <b id="life-left">'+left.toFixed(1)+' dias</b></span></div><div class="progress life-progress"><i id="life-progress" style="width:'+Math.max(0,Math.min(100,left/7*100))+'%"></i></div>')+'<p class="stock-hint">'+(low?'📦 Está acabando.':'')+'</p>';}
 function personaKnowledge(id){const n=Object.values(g.learning?.facts||{}).filter(f=>['product','minimum'].includes(f.kind)&&f.productId===g.productId&&f.personaId===id).length;return n?'<small class="persona-memory">📘 '+n+' descoberta(s) guardada(s)</small>':'';}
 function productKnowledge(axis){const a=C.Learning.productHint(g,axis),m=C.Learning.minimumHint(g,axis);return '<span class="knowledge-badge '+(a?'confirmed':'unknown')+'" title="'+esc(a?a.text:'Ainda não investigado para este produto e persona')+'">'+esc(a?.symbol||'?')+'</span>'+(m?'<span class="knowledge-badge need" title="'+esc(m.text)+'">!</span>':'');}
 function campaignKnowledge(channel){const hints=C.Learning.channelHints(g,channel);return '<small class="channel-knowledge">'+(hints.length?hints.map(f=>esc(C.Reach.ages[f.age])+' <b class="knowledge-badge confirmed">'+esc(f.symbol)+'</b>').join(' · '):'Afinidades a descobrir · ?')+'</small>';}
 function learningPrompt(){if(!g.unitAcquisition)return '';const r=C.Learning.record(g),ready=['product','campaign'].some(d=>C.Learning.status(g,d).ready);return '<aside class="learning-invite"><span class="learning-lamp">💡</span><div><b>'+ (r?(r.cards.length?'Uma descoberta para a próxima decisão.':'A experiência ficou guardada.'):'O que essa experiência pode ensinar?')+'</b><small>'+(r?'A tentativa desta campanha já foi registrada.':ready?'Conhecimento fica na empresa e reaparece nas próximas criações.':'Precisamos de mais evidências ou de um experimento diferente.')+'</small></div>'+button(r?'Rever investigação':'Tirar uma lição 🎲','learningOpen',!r&&!ready?'disabled':'','secondary')+'</aside>';}
 function learningPanel(){const k=g.learning,record=C.Learning.record(g),domain=k.domain||'product',leader=C.Learning.leader(g,domain),mods=C.Learning.modifiers(g,domain),bonus=mods.reduce((n,m)=>n+m.value,0),hidden=!!rolling,m=C.windowMetrics(g);chooseGuide('DEPOIS DO EXPEDIENTE','Vamos ligar os pontos.','');const facts='<p class="learning-facts">'+m.seen+' contatos · '+m.sold+' unidades vendidas · operação '+money(m.operatingProfit)+'</p>';if(record)return facts+'<div class="learning-scene">'+dieHTML(record.roll,null)+'<div class="learning-copy">'+(hidden?'<h2>Ligando os pontos…</h2><p>A equipe procura uma conclusão.</p>':'<h2>'+(record.cards.length?'💡 Descoberta registrada!':'Ainda falta ligar os pontos.')+'</h2>'+formula(record.roll)+'<p>Alvo 11 · '+esc(record.analyst)+'</p>'+(record.cards.length?'<div class="knowledge-rewards">'+record.cards.map(f=>'<article class="knowledge-card"><strong>'+esc(f.symbol)+'</strong><h3>'+esc(f.title)+'</h3><p>'+esc(f.text)+'</p><small>Guardado na memória da empresa</small></article>').join('')+'</div>':'<p>Seus feedbacks e resultados continuam disponíveis. A intuição acumulada ajudará na próxima experiência deste assunto.</p>'))+'</div></div><div class="tray-foot">'+(hidden?'':button('Voltar ao quarto','learningClose'))+'</div>';
 return facts+'<div class="learning-domains">'+[{id:'product',name:'Produto',icon:'🎧',question:'O que importa para essa persona?'},{id:'campaign',name:'Campanha',icon:'📣',question:'Quem descobre novidades por aqui?'}].map(d=>{const status=C.Learning.status(g,d.id);return button('<span>'+d.icon+'</span><b>'+d.name+'</b><small>'+d.question+'</small><small>'+esc(status.reason)+'</small>','learningDomain','data-domain="'+d.id+'" '+(!status.ready?'disabled':''),domain===d.id?'selected':'secondary');}).join('')+'</div><div class="learning-scene">'+dieHTML(null,'learningRoll')+'<div class="learning-copy"><h2>D20 + '+bonus+' · alvo 11</h2><p>'+esc(leader.name)+' · análise +'+leader.skill+(k.intuition[domain]?' · intuição +'+k.intuition[domain]:'')+'</p><p>'+Math.min(80,50+bonus*5)+'% de chance · uma tentativa nesta campanha</p>'+(C.Learning.analysts(g).length>1?'<div class="price-tags">'+C.Learning.analysts(g).map(p=>button(esc(p.name)+' · +'+(p.skills[domain]||0),'learningAnalyst','data-id="'+esc(p.id)+'"',p.id===leader.id?'selected':'secondary')).join('')+'</div>':'')+button('Investigar com D20 🎲','learningRoll')+'</div></div><div class="tray-foot">'+button('Voltar sem investigar','learningClose','','secondary')+'</div>';}
 function venueNotes(id){const hints=C.Learning.venueHints(g,id);return '<small class="channel-knowledge">'+(hints.length?hints.map(f=>C.Reach.ages[f.age]+' <b class="knowledge-badge confirmed">'+esc(f.symbol)+'</b>').join(' · '):'Afinidades ainda não investigadas · ?')+'</small>';}
 function materialPanel(){const rows=[...(g.stock>0?[{id:'current',name:g.name,stock:g.stock}]:[]),...g.portfolio.filter(p=>p.stock>0&&p.account).map(p=>({id:p.account.id,name:p.name,stock:p.stock}))];return '<section class="material-panel"><h3>♻ Matérias-primas recuperadas: '+money(g.materialsCredit||0)+'</h3><small>Recupere 80% em materiais para a próxima produção.</small>'+rows.map(p=>{const q=C.dismantleQuote(g,p.id,p.stock);return '<div class="material-row"><span>'+esc(p.name)+' · '+p.stock+' unidades · recupera '+money(q.credit)+'</span>'+button('Desmontar este estoque','requestDismantle','data-id="'+esc(p.id)+'" data-quantity="'+p.stock+'" '+(p.id==='current'&&g.crew?'disabled':''),'secondary')+'</div>';}).join('')+(scrapConfirm?'<div class="inline-confirm"><b>Desmontar '+scrapConfirm.quantity+' unidades? Essa operação consome o estoque.</b>'+button('Confirmar desmontagem','dismantle','data-id="'+esc(scrapConfirm.id)+'" data-quantity="'+scrapConfirm.quantity+'"')+button('Voltar','scrapCancel','','secondary')+'</div>':'')+'</section>';}
 function modernUpgrade(){const u=g.upgrade,redistribute=u.mode==='redistribute';chooseGuide('NOVA GERAÇÃO',redistribute?'Uma nova abordagem.':'Vamos tentar ir além.','');return '<div class="campaign-kinds">'+button('Evoluir · NV '+(g.level+1),'upgradeMode','data-mode="level" '+(g.level>=10?'disabled':''),!redistribute?'selected':'secondary')+button('Redistribuir · R$750','upgradeMode','data-mode="redistribute"',redistribute?'selected':'secondary')+'</div><div class="version-desk"><label>Nome da versão <input id="upgrade-name" value="'+esc(u.name)+'" maxlength="28"></label><span class="investment-tag">'+money(u.cost)+'</span></div>'+(redistribute&&g.boardCampaign?'<div class="evolution-promise">'+gadgetArt()+'<div><h2>Remontar na prancheta</h2><p>Mesmo nível ('+g.level+'). Você escolhe quais peças manter e encaixa novas, sem rolar dado.</p></div></div>':redistribute?'<div class="design-lab">'+radar(u.attributes)+'<div><p>'+C.G.U.total(u.attributes)+' / '+u.budget+' pontos · mesmo nível</p>'+C.axes(g).map(a=>'<div class="attribute"><b>'+a.name+' '+productKnowledge(a.id)+'</b>'+button('−','upgradePoint','data-id="'+a.id+'" data-delta="-1"','secondary')+'<strong>'+u.attributes[a.id]+'</strong>'+button('+','upgradePoint','data-id="'+a.id+'" data-delta="1"','secondary')+'</div>').join('')+'</div></div>':'<div class="evolution-promise">'+gadgetArt()+'<div><h2>NV '+g.level+' <span>→</span> '+(g.level+1)+'</h2><p>'+C.G.U.total(g.attributes)+' pontos no projeto atual · até '+u.budget+' na próxima versão</p><p class="roll-target">🎲 Teste da evolução: <b>sucesso a partir de '+u.difficulty+' no D20</b> · chance de '+Math.round(Math.max(0,Math.min(19,21-u.difficulty))/20*100)+'% sem bônus. Se falhar, dá para rolar de novo por '+money(Math.round(u.cost/3))+'.</p>'+(g.reviews.length?'<blockquote>“'+esc(g.reviews.at(-1).feedback)+'”</blockquote>':'')+'</div></div>')+materialPanel()+'<div class="tray-foot">'+button('Voltar','upgradeCancel','','secondary')+button(redistribute?'Aplicar projeto · R$750':'Desenvolver · '+money(u.cost),redistribute?'redistributionCommit':'upgradeStart',g.cash<u.cost+C.upgradeLaunchReserve(g)?'disabled':'')+'</div>';}

 function modernSales(){chooseGuide('PORTAS ABERTAS',g.name,'');const q=g.restockSize,total=C.batchTotal(g,q),paid=C.materialPayment(g,total);let controls=g.crew?'<b>Produzindo '+g.crew.quantity+' unidades.</b>':button(stockPlanOpen?'Fechar reposição':'Repor estoque','stockPlanToggle','','secondary');if(!g.crew&&stockPlanOpen)controls+=batchControls(true)+'<p id="restock-cost">Custo do lote: '+money(total)+' · dinheiro: '+money(paid)+'.</p>'+button('Confirmar produção · '+money(paid),'crew','id="restock-confirm" data-task="produce" data-quantity="'+q+'" '+(g.cash<paid?'disabled':''));return '<div class="sales-main"><h2 id="sales-count">'+g.sold+' unidades vendidas · '+money(g.revenue)+' de faturamento</h2><div id="break-even-live">'+breakEven()+fadeNote()+'</div><p><span id="sales-contacts">'+g.sales.seen+' de '+g.leads+'</span> contatos atendidos · preço '+money(g.price)+(g.traction?' · E-commerce':' · CAC '+money(C.cac(g))+'/un.')+'</p><div class="crew-controls">'+controls+'</div></div>';}

 const weekdayNames=['SEG','TER','QUA','QUI','SEX'];
 let weeklyHistoryOpen=false;
 function weeklyHistory(){
  const reports=g.weekly.reports;
  if(!reports.length)return '<p>O primeiro fechamento aparece na sexta-feira.</p>';
  const max=Math.max(1,...reports.flatMap(r=>[r.revenue,r.costs,Math.abs(r.result),Math.abs(r.cashEnd)]));
  const legend='<div class="week-legend">Receita <i></i> Custos <i></i> Resultado <i></i> Caixa <i></i></div>';
  return legend+reports.map(r=>'<div class="week-chart"><b>S'+r.number+'</b>'+['revenue','costs','result','cashEnd'].map(key=>
   '<div class="week-bar '+key+'" title="'+money(r[key])+'"><i style="width:'+Math.abs(r[key])/max*100+'%"></i><span>'+money(r[key])+'</span></div>').join('')+(r.audience===undefined?'':'<small class="growth-week">'+r.audience.toLocaleString('pt-BR')+' na audiência · reputação '+Math.round(r.reputation)+'/100</small>')+'</div>').join('');
 }
