 const channelColors=['#40968e','#d7953d','#8b78b9','#bf6e62','#688bb5','#729453'];

 function growthCard(mix=g.traction){
  const state=g.phase==='recampaignPlan'&&g.campaignDraft.clientId?{...g,clientId:g.campaignDraft.clientId}:g;
  const profile=C.Reach.growthProfile(state);
  if(!profile)return '';
  const used=1-profile.segment.available/profile.capacity;
  const condition=used>=.7?'Saturado':used>=.35?'Em desgaste':used>0?'Em uso':'Novo';
  const estimate=C.Reach.plan(state,{mix}).total;
  const fmt=n=>n.toLocaleString('pt-BR');
  return '<section class="growth-card"><small>MERCADO · '+esc(C.client(state)?.name)+'</small>'+
   '<div><span>Audiência da empresa <b>'+fmt(profile.audience)+'</b></span><span>Reputação <b>'+Math.round(profile.reputation)+'/100</b></span>'+
   '<span>Distribuição <b>'+fmt(profile.distribution)+'×</b></span><span>Público '+condition.toLowerCase()+' <b>'+Math.round(used*100)+'% exposto</b></span></div>'+
   '<div class="growth-meter" role="img" aria-label="'+Math.round(used*100)+'% do público exposto"><i style="width:'+used*100+'%"></i></div>'+
   '<p>Potencial neste nicho <b>'+fmt(profile.capacity)+'</b> · previsão <b>'+fmt(estimate)+' interessados</b> '+(state.boardCampaign?'numa campanha média':'com dado normal')+'.</p></section>';
 }
