 function mixLegend(mix){
  return mix.map((value,i)=>'<span style="border-color:'+channelColors[i]+'">'+C.Reach.channelNames(g)[i]+' '+value+'%</span>').join(' ');
 }
 function normalizeMix(weights){
  const total=weights.reduce((sum,v)=>sum+v,0);
  if(!total)return C.Reach.defaultMix();
  const shares=weights.map(v=>100*v/total);
  const mix=shares.map(Math.floor);
  const order=shares.map((v,i)=>({i,remainder:v-mix[i]})).sort((a,b)=>b.remainder-a.remainder);
  const missing=100-mix.reduce((sum,v)=>sum+v,0);
  for(let i=0;i<missing;i++)mix[order[i].i]++;
  return mix;
 }
