 function openSocial(){
  if(!g.social||blocked)return;
  try{
   const next=C.act(g,{type:'socialSeen'});
   persist(next);g=next;
   socialAuthor=null;socialLimit=30;socialTab='all';socialOpen=true;
   render();
  }catch(e){fail(e);}
 }
